const rawText = $input.first().json.text || "";
let jsonStr = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();

let content = {
    originalTopic: "N/A",
    rewrittenPost: "N/A",
    suggestedHashtags: "",
    contentCategory: "N/A",
    originalText: $("Loop Over Posts").item.json.text || $("Loop Over Posts").item.json.postText || $("Loop Over Posts").item.json.content || "",
    originalAuthor: $("Loop Over Posts").item.json.authorName || $("Loop Over Posts").item.json.author || "Unknown",
    originalUrl: $("Loop Over Posts").item.json.url || $("Loop Over Posts").item.json.postUrl || $("Loop Over Posts").item.json.permalink || "",
    scrapedAt: new Date().toISOString()
};

try {
    const parsed = JSON.parse(jsonStr);
    content = { ...content, ...parsed };
} catch (e) {
    // fallback
}

return [{ json: content }];

const rawText = $input.first().json.text || "";
let jsonStr = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();

let verdict = "not_relevant";
let reason = "";

try {
    const parsed = JSON.parse(jsonStr);
    verdict = parsed.verdict || "not_relevant";
    reason = parsed.reason || "";
} catch (e) {
    if (jsonStr.toLowerCase().includes('"verdict": "relevant"') || jsonStr.toLowerCase().includes('"verdict":"relevant"')) {
        verdict = "relevant";
    }
}

return [{
    json: {
        verdict: verdict,
        reason: reason,
        text: $("Loop Over Posts").item.json.text || $("Loop Over Posts").item.json.postText || $("Loop Over Posts").item.json.content || "",
        authorName: $("Loop Over Posts").item.json.authorName || $("Loop Over Posts").item.json.author || "Unknown",
        url: $("Loop Over Posts").item.json.url || $("Loop Over Posts").item.json.postUrl || $("Loop Over Posts").item.json.permalink || ""
    }
}];
